from flask import Blueprint, jsonify, request
from app.models.problem import Problem

def problem_blueprint():
    blueprint = Blueprint('problem', __name__)

    # Route for getting all problems
    @blueprint.route('/problems', methods=['GET'])
    def get_problems():
        problems = Problem.query.all()
        return jsonify([problem.to_dict() for problem in problems]), 200

    # Route for getting a specific problem by ID
    @blueprint.route('/problems/<int:problem_id>', methods=['GET'])
    def get_problem(problem_id):
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({'error': 'Problem not found'}), 404
        return jsonify(problem.to_dict()), 200

    # Route for creating a new problem
    @blueprint.route('/problems', methods=['POST'])
    def create_problem():
        data = request.json
        if not data or not data.get('title') or not data.get('description'):
            return jsonify({'error': 'Invalid data'}), 400

        new_problem = Problem(
            title=data.get('title'),
            description=data.get('description'),
            difficulty=data.get('difficulty', 'Easy')
        )
        new_problem.save()
        return jsonify(new_problem.to_dict()), 201

    # Route for updating a problem
    @blueprint.route('/problems/<int:problem_id>', methods=['PUT'])
    def update_problem(problem_id):
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({'error': 'Problem not found'}), 404

        data = request.json
        if not data:
            return jsonify({'error': 'Invalid data'}), 400

        problem.title = data.get('title', problem.title)
        problem.description = data.get('description', problem.description)
        problem.difficulty = data.get('difficulty', problem.difficulty)
        problem.save()
        return jsonify(problem.to_dict()), 200

    # Route for deleting a problem
    @blueprint.route('/problems/<int:problem_id>', methods=['DELETE'])
    def delete_problem(problem_id):
        problem = Problem.query.get(problem_id)
        if not problem:
            return jsonify({'error': 'Problem not found'}), 404

        problem.delete()
        return jsonify({'message': 'Problem deleted successfully'}), 200

    return blueprint

from flask import Blueprint, jsonify, request
from app.models.user import User

def user_blueprint():
    user_bp = Blueprint('user', __name__)

    @user_bp.route('/users', methods=['GET'])
    def get_users():
        users = User.query.all()
        return jsonify([user.to_dict() for user in users]), 200

    @user_bp.route('/users/<int:user_id>', methods=['GET'])
    def get_user(user_id):
        user = User.query.get(user_id)
        if user:
            return jsonify(user.to_dict()), 200
        return jsonify({'error': 'User not found'}), 404

    @user_bp.route('/users', methods=['POST'])
    def create_user():
        data = request.get_json()
        if not data:
            return jsonify({'error': 'Invalid input'}), 400
        user = User(**data)
        try:
            user.save()
            return jsonify(user.to_dict()), 201
        except Exception as e:
            return jsonify({'error': str(e)}), 400

    @user_bp.route('/users/<int:user_id>', methods=['PUT'])
    def update_user(user_id):
        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404
        data = request.get_json()
        try:
            for key, value in data.items():
                setattr(user, key, value)
            user.save()
            return jsonify(user.to_dict()), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 400

    @user_bp.route('/users/<int:user_id>', methods=['DELETE'])
    def delete_user(user_id):
        user = User.query.get(user_id)
        if not user:
            return jsonify({'error': 'User not found'}), 404
        try:
            user.delete()
            return jsonify({'message': f'User {user_id} deleted successfully'}), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 400

    return user_bp

from flask import Blueprint, jsonify, request
from app.models.solution import Solution

def solution_blueprint():
    solution_bp = Blueprint('solutions', __name__)

    @solution_bp.route('/solutions', methods=['GET'])
    def get_solutions():
        """Retrieve all solutions."""
        solutions = Solution.query.all()
        solutions_data = [solution.as_dict() for solution in solutions]
        return jsonify(solutions_data), 200

    @solution_bp.route('/solutions/<int:solution_id>', methods=['GET'])
    def get_solution(solution_id):
        """Retrieve a solution by its ID."""
        solution = Solution.query.get(solution_id)
        if not solution:
            return jsonify({'error': 'Solution not found'}), 404
        return jsonify(solution.as_dict()), 200

    @solution_bp.route('/solutions', methods=['POST'])
    def create_solution():
        """Create a new solution."""
        data = request.get_json()
        if not data:
            return jsonify({'error': 'Invalid input'}), 400
        try:
            new_solution = Solution(**data)
            new_solution.save()
            return jsonify(new_solution.as_dict()), 201
        except Exception as e:
            return jsonify({'error': str(e)}), 400

    @solution_bp.route('/solutions/<int:solution_id>', methods=['PUT'])
    def update_solution(solution_id):
        """Update an existing solution."""
        solution = Solution.query.get(solution_id)
        if not solution:
            return jsonify({'error': 'Solution not found'}), 404
        data = request.get_json()
        if not data:
            return jsonify({'error': 'Invalid input'}), 400
        try:
            for key, value in data.items():
                setattr(solution, key, value)
            solution.save()
            return jsonify(solution.as_dict()), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 400

    @solution_bp.route('/solutions/<int:solution_id>', methods=['DELETE'])
    def delete_solution(solution_id):
        """Delete a solution by its ID."""
        solution = Solution.query.get(solution_id)
        if not solution:
            return jsonify({'error': 'Solution not found'}), 404
        try:
            solution.delete()
            return jsonify({'message': 'Solution deleted successfully'}), 200
        except Exception as e:
            return jsonify({'error': str(e)}), 400

    return solution_bp

